  1→"""
  2→Synapse Design System — Qt Stylesheet Generator
  3→
  4→Generates QSS (Qt Style Sheets) from design tokens for the Synapse panel.
  5→Houdini 21+ uses PySide6/Qt6; older versions use PySide2/Qt5.
  6→
  7→Usage:
  8→    from synapse_styles import generate_stylesheet, STATUS_STYLES
  9→    widget.setStyleSheet(generate_stylesheet())
 10→"""
 11→
 12→import sys
 13→import os
 14→
 15→# Allow importing tokens from the design directory
 16→_design_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)))
 17→if _design_dir not in sys.path:
 18→    sys.path.insert(0, _design_dir)
 19→
 20→from tokens import (
 21→    SIGNAL, VOID, NEAR_BLACK, CARBON, GRAPHITE, SLATE, SILVER, BONE, WHITE,
 22→    FIRE, GROW, WARN, ERROR,
 23→    FONT_MONO, FONT_MONO_FALLBACKS, FONT_SANS, FONT_SANS_FALLBACKS,
 24→    SIZE_LABEL, SIZE_SMALL, SIZE_UI, SIZE_BODY, SIZE_TITLE, SIZE_HERO,
 25→    SPACE_XS, SPACE_SM, SPACE_MD, SPACE_LG,
 26→    STATES,
 27→)
 28→
 29→
 30→def _font_family(primary, fallbacks):
 31→    """Build a CSS font-family string."""
 32→    fonts = [primary] + list(fallbacks)
 33→    return ", ".join(f'"{f}"' for f in fonts)
 34→
 35→
 36→MONO_FAMILY = _font_family(FONT_MONO, FONT_MONO_FALLBACKS)
 37→SANS_FAMILY = _font_family(FONT_SANS, FONT_SANS_FALLBACKS)
 38→
 39→
 40→def generate_stylesheet():
 41→    """Generate the full QSS stylesheet for the Synapse panel."""
 42→    return f"""
 43→/* ═══════════════════════════════════════════════════════
 44→   SYNAPSE DESIGN SYSTEM — Qt Stylesheet
 45→   Generated from design tokens. Do not edit directly.
 46→   ═══════════════════════════════════════════════════════ */
 47→
 48→/* ── Base Panel ──────────────────────────────────────── */
 49→
 50→QWidget#synapse_panel {{
 51→    background-color: {NEAR_BLACK};
 52→    color: {BONE};
 53→    font-family: {SANS_FAMILY};
 54→    font-size: {SIZE_BODY}px;
 55→}}
 56→
 57→/* ── Title Bar ───────────────────────────────────────── */
 58→
 59→QFrame#title_bar {{
 60→    background-color: {VOID};
 61→    border-bottom: 1px solid {GRAPHITE};
 62→    padding: {SPACE_SM}px {SPACE_MD}px;
 63→    min-height: 64px;
 64→    max-height: 64px;
 65→}}
 66→
 67→QLabel#title_label {{
 68→    color: {WHITE};
 69→    font-family: {MONO_FAMILY};
 70→    font-size: {SIZE_HERO}px;
 71→    font-weight: 600;
 72→    letter-spacing: 4px;
 73→}}
 74→
 75→QLabel#version_label {{
 76→    color: {SLATE};
 77→    font-family: {MONO_FAMILY};
 78→    font-size: {SIZE_LABEL}px;
 79→}}
 80→
 81→/* ── Status Bar ──────────────────────────────────────── */
 82→
 83→QFrame#status_bar {{
 84→    background-color: {CARBON};
 85→    border-bottom: 1px solid {GRAPHITE};
 86→    padding: {SPACE_SM}px {SPACE_MD}px;
 87→    min-height: 48px;
 88→    max-height: 48px;
 89→}}
 90→
 91→QLabel#status_dot {{
 92→    font-size: 18px;
 93→    min-width: 18px;
 94→    max-width: 18px;
 95→}}
 96→
 97→QLabel#status_label {{
 98→    color: {SILVER};
 99→    font-family: {MONO_FAMILY};
100→    font-size: {SIZE_SMALL}px;
101→    letter-spacing: 1px;
102→}}
103→
104→QLabel#status_detail {{
105→    color: {SLATE};
106→    font-family: {MONO_FAMILY};
107→    font-size: {SIZE_LABEL}px;
108→}}
109→
110→/* ── Tool Grid ───────────────────────────────────────── */
111→
112→QFrame#tool_grid {{
113→    background-color: transparent;
114→    padding: {SPACE_SM}px;
115→}}
116→
117→QPushButton.tool_button {{
118→    background-color: {CARBON};
119→    color: {BONE};
120→    border: 1px solid {GRAPHITE};
121→    border-radius: 4px;
122→    font-family: {MONO_FAMILY};
123→    font-size: {SIZE_UI}px;
124→    padding: {SPACE_SM}px;
125→    min-height: 80px;
126→    text-align: center;
127→}}
128→
129→QPushButton.tool_button:hover {{
130→    background-color: #484848;
131→    border-color: {SIGNAL};
132→    color: {WHITE};
133→}}
134→
135→QPushButton.tool_button:pressed {{
136→    background-color: rgba(0, 212, 255, 0.15);
137→    border-color: {SIGNAL};
138→    color: {SIGNAL};
139→}}
140→
141→QPushButton.tool_button:disabled {{
142→    background-color: {NEAR_BLACK};
143→    color: {SLATE};
144→    border-color: {GRAPHITE};
145→}}
146→
147→/* ── Activity Log ────────────────────────────────────── */
148→
149→QFrame#activity_frame {{
150→    background-color: transparent;
151→    padding: 0px {SPACE_SM}px;
152→}}
153→
154→QLabel#activity_header {{
155→    color: {SLATE};
156→    font-family: {MONO_FAMILY};
157→    font-size: {SIZE_LABEL}px;
158→    letter-spacing: 2px;
159→    padding: {SPACE_XS}px 0px;
160→}}
161→
162→QTextEdit#activity_log {{
163→    background-color: {VOID};
164→    color: {SILVER};
165→    border: 1px solid {GRAPHITE};
166→    border-radius: 4px;
167→    font-family: {MONO_FAMILY};
168→    font-size: {SIZE_SMALL}px;
169→    padding: {SPACE_SM}px;
170→    selection-background-color: rgba(0, 212, 255, 0.3);
171→    selection-color: {WHITE};
172→}}
173→
174→QScrollBar:vertical {{
175→    background-color: {VOID};
176→    width: 10px;
177→    margin: 0px;
178→}}
179→
180→QScrollBar::handle:vertical {{
181→    background-color: {GRAPHITE};
182→    border-radius: 5px;
183→    min-height: 30px;
184→}}
185→
186→QScrollBar::handle:vertical:hover {{
187→    background-color: {SLATE};
188→}}
189→
190→QScrollBar::add-line:vertical,
191→QScrollBar::sub-line:vertical {{
192→    height: 0px;
193→}}
194→
195→QScrollBar::add-page:vertical,
196→QScrollBar::sub-page:vertical {{
197→    background-color: transparent;
198→}}
199→
200→/* ── Connection Controls ─────────────────────────────── */
201→
202→QFrame#connection_frame {{
203→    background-color: {CARBON};
204→    border-top: 1px solid {GRAPHITE};
205→    padding: {SPACE_SM}px {SPACE_MD}px;
206→    min-height: 52px;
207→    max-height: 52px;
208→}}
209→
210→QPushButton#connect_button {{
211→    background-color: transparent;
212→    color: {SIGNAL};
213→    border: 1px solid {SIGNAL};
214→    border-radius: 3px;
215→    font-family: {MONO_FAMILY};
216→    font-size: {SIZE_SMALL}px;
217→    padding: {SPACE_XS}px {SPACE_SM}px;
218→    min-width: 120px;
219→}}
220→
221→QPushButton#connect_button:hover {{
222→    background-color: rgba(0, 212, 255, 0.1);
223→}}
224→
225→QPushButton#connect_button:pressed {{
226→    background-color: rgba(0, 212, 255, 0.2);
227→}}
228→
229→QPushButton#ws_path_button {{
230→    background-color: transparent;
231→    color: {SLATE};
232→    border: 1px solid {GRAPHITE};
233→    border-radius: 3px;
234→    font-family: {MONO_FAMILY};
235→    font-size: {SIZE_LABEL}px;
236→    padding: {SPACE_XS}px {SPACE_SM}px;
237→}}
238→
239→QPushButton#ws_path_button:hover {{
240→    color: {SIGNAL};
241→    border-color: {SIGNAL};
242→    background-color: rgba(0, 212, 255, 0.1);
243→}}
244→
245→QPushButton#ws_path_button:pressed {{
246→    background-color: rgba(0, 212, 255, 0.2);
247→}}
248→
249→/* ── Tooltip ─────────────────────────────────────────── */
250→
251→QToolTip {{
252→    background-color: {CARBON};
253→    color: {BONE};
254→    border: 1px solid {GRAPHITE};
255→    font-family: {SANS_FAMILY};
256→    font-size: {SIZE_SMALL}px;
257→    padding: {SPACE_XS}px {SPACE_SM}px;
258→}}
259→"""
260→
261→
262→# ── Status-specific styles ──────────────────────────────
263→
264→STATUS_STYLES = {}
265→for state_name, state_info in STATES.items():
266→    STATUS_STYLES[state_name] = f"""
267→        QLabel#status_dot {{ color: {state_info['color']}; }}
268→        QLabel#status_label {{ color: {state_info['color']}; }}
269→    """
270→
271→
272→# ── Convenience: animation keyframes as color tuples ────
273→
274→STATUS_COLORS = {name: info["color"] for name, info in STATES.items()}
275→
276→
277→if __name__ == "__main__":
278→    print("=" * 50)
279→    print("  SYNAPSE QSS STYLESHEET")
280→    print("=" * 50)
281→    qss = generate_stylesheet()
282→    print(f"\nStylesheet length: {len(qss)} characters")
283→    print(f"Status styles: {list(STATUS_STYLES.keys())}")
284→    print("\n--- Preview (first 500 chars) ---")
285→    print(qss[:500])
286→    print("...")
287→
